action_details.action_postfix:
// Physical nexus established - filing required
true result.mn_has_nexus xdef
"Minnesota filing required: Physical presence (office, employees, or property in state)" job.audit_trail swap addto

// Economic nexus established per Wayfair - filing required
true result.mn_has_nexus xdef
"Minnesota filing required: Economic nexus (exceeds $100,000 gross receipts threshold)" job.audit_trail swap addto

// Calculate Minnesota state additions
0.0 /mn_additions xdef

// Common Minnesota additions:
// - Federal bond interest (not taxable federally but taxable to MN)
// - State-specific addbacks

result.mn_us_interest_income 0.0 ne
{
  mn_additions result.mn_us_interest_income add /mn_additions xdef
} if

mn_additions result.mn_state_additions xdef

// Calculate Minnesota state subtractions
0.0 /mn_subtractions xdef

// Common Minnesota subtractions:
// - State income taxes deducted on federal return
// - Minnesota NOL deduction

result.mn_municipal_interest 0.0 ne
{
  mn_subtractions result.mn_municipal_interest add /mn_subtractions xdef
} if

mn_subtractions result.mn_state_subtractions xdef

"Minnesota additions: $" result.mn_state_additions cvs strconcat ", subtractions: $" strconcat result.mn_state_subtractions cvs strconcat job.audit_trail swap addto

// Calculate Minnesota taxable income // Federal taxable income apportioned to MN + additions - subtractions result.mn_apportioned_income result.mn_state_additions add result.mn_state_subtractions sub 0.0 max result.mn_taxable_income xdef
// Calculate Minnesota tax using flat rate: 9.5% result.mn_taxable_income result.mn_corp_tax_rate mul /mn_tax_before_credits xdef
// Subtract Minnesota state credits mn_tax_before_credits result.mn_state_credits sub 0.0 max result.mn_tax_liability xdef
// Calculate refund or amount owed result.mn_estimated_payments result.mn_tax_liability sub result.mn_refund_or_owed xdef
"Minnesota taxable income: $" result.mn_taxable_income cvs strconcat job.audit_trail swap addto "Minnesota tax liability (9.5%): $" result.mn_tax_liability cvs strconcat job.audit_trail swap addto
